meesages_on_air.messages= messages;
try
{
    var json = JSON.parse(str_aux);
    var json_data =JSON.parse(json["data"]);

    for(var i=0;i<json_data["missatges"].length;i++)
    {
       var message =
       {
           "status": json_data["missatges"][i]["Status"],
           "zones": json_data["missatges"][i]["Zones"],
           "system_id": json_data["missatges"][i]["Id"],
           "sender_ip": json_data["missatges"][i]["SenderIp"],
           "messagesIds": json_data["missatges"][i]["Prerecorded"] ? json_data["missatges"][i]["Prerecorded"]["messages"]  : "",
           "messages_names": json_data["missatges"][i]["Prerecorded"] ? json_data["missatges"][i]["Prerecorded"]["messages_names"] : "",
           "type_message": json_data["missatges"][i]["InputTag"]

       }
        meesages_on_air.messages.push(message);

    }

}catch (error)
{
    LOG.info(error);
}
return JSON.stringify(meesages_on_air);

var command_parameters = JSON.parse(start_paging_command.value);
