    }

}catch (error)
{
    LOG.info(error);
}
return JSON.stringify(meesages_on_air);

var command_parameters = JSON.parse(start_paging_command.value);
for(var i = 0;i< command_parameters["zones"].length;i++)
{
    var prerecorded = 
    {
        "repetitions": command_parameters["repetitions"],
        "interval": 0,
        "period": 0,
        "start_time": 0,
        "stop_time": 0,
        "playing_message": 0,
        "sequence": 0,
        "messages": command_parameters["messages"],
        "messages_names": []
    }
    var data = {
        "SenderIp": "", 
        "SenderInput": -1,
        "InputTag": "",
        "Type": 1,
        "Priority": 255,
        "Chime": 0,
        "Id": -1,
        "Zones": [command_parameters["zones"][i]],
        "Groups": [],
        "Prerecorded": prerecorded

    }

    var json = {
        "version":  "1",
        "command":  "start_prerecorded",
        "type": "set",
        "data": JSON.stringify(data)
    }
    var hex_command = a2hex(JSON.stringify(json));
    hex_command += "00";
    write_command.set(hex_command);
}

return start_paging_command.value;

